using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var resultStore = new DiskBasedResultStore(
            Path.Combine(Environment.CurrentDirectory, ".evaluation-reports"));

        s_reportingConfiguration = new ReportingConfiguration(
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            resultStore: resultStore,
            chatConfiguration: GetChatConfiguration());
    }

    [TestMethod]
    public async Task GreetingResponse_MeetsQualityBar()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(GreetingResponse_MeetsQualityBar));

        IChatClient chatClient = run.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        EvaluationResult result = await run.EvaluateAsync(messages, response);

        AssertMetricAboveThreshold(result, nameof(CoherenceEvaluator), 3);
        AssertMetricAboveThreshold(result, nameof(FluencyEvaluator), 3);
    }

    [TestMethod]
    public async Task FactualQuestion_IsRelevantAndGrounded()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(FactualQuestion_IsRelevantAndGrounded));

        IChatClient chatClient = run.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        EvaluationResult result = await run.EvaluateAsync(messages, response);

        AssertMetricAboveThreshold(result, nameof(RelevanceEvaluator), 3);
        AssertMetricAboveThreshold(result, nameof(GroundednessEvaluator), 3);
    }

    private static void AssertMetricAboveThreshold(
        EvaluationResult result, string metricName, double threshold)
    {
        var metric = result.Metrics.Values
            .OfType<NumericMetric>()
            .FirstOrDefault(m => m.Name.Contains(metricName, StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(metric, $"Metric '{metricName}' not found in results.");
        Assert.IsTrue(
            metric.Value >= threshold,
            $"Metric '{metric.Name}' value {metric.Value} is below threshold {threshold}.");
    }

