         messages.AddRange(response.Messages);

         EvaluationResult result = await run.EvaluateAsync(messages, response);

         AssertMetricAboveThreshold(result, nameof(RelevanceEvaluator), 3);
         AssertMetricAboveThreshold(result, nameof(GroundednessEvaluator), 3);
     }

     private static void AssertMetricAboveThreshold(
         EvaluationResult result, string metricName, double threshold)
     {
         var metric = result.Metrics.Values
             .OfType<NumericMetric>()
             .FirstOrDefault(m => m.Name.Contains(metricName, StringComparison.OrdinalIgnoreCase));

         Assert.IsNotNull(metric, $"Metric '{metricName}' not found in results.");
         Assert.IsGreaterThanOrEqualTo(
             metric.Value!.Value,
             threshold,
             $"Metric '{metric.Name}' value {metric.Value} is below threshold {threshold}.");
     }

     private static ChatConfiguration GetChatConfiguration()
     {
         var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
             ?? "https://your-resource.openai.azure.com/";
         var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
             ?? "gpt-4o";

         IChatClient chatClient =
             new AzureOpenAIClient(new Uri(endpoint), new DefaultAzureCredential())
                 .GetChatClient(deployment)
                 .AsIChatClient();

         return new ChatConfiguration(chatClient);
     }
 }

